cd /home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon && python3 - <<'EOF'
import yaml,glob,os
live={'ajc-pic0av','ajc-fbc','ajc-albanese','ajcr-cert-r2','ajcr-divrep','ajcr-charts','ajcr-w5-av','ajc-rr'}
items={}
for f in glob.glob('roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f)); items[d['id']]=d
def parent(i): return (items[i].get('metadata') or {}).get('parent')
active=[i for i,d in items.items() if d.get('status')=='active']
# rows directly held by a live lane
direct={i for i in active if (items[i].get('metadata') or {}).get('owner') in live}
# ancestors of any live-held row (any status)
anc=set()
for i in direct:
    p=parent(i)
    while p:
        anc.add(p); p=parent(p)
print('ACTIVE ROWS:',len(active))
for i in sorted(active):
    md=items[i].get('metadata') or {}
    tag='DIRECT(live)' if i in direct else ('ANCESTOR' if i in anc else 'LEFTOVER')
    print(f'  {tag:14} {i}  owner={md.get("owner")} updated={md.get("updated_at","")[:10]}')
print()
# tasks
print('=== tasks ===')
for f in sorted(glob.glob('tasks/items/*.yaml')):
    d=yaml.safe_load(open(f))
    md=d.get('metadata') or {}
    print(f"{d['id']:22} {d.get('status'):10} upd={md.get('updated_at','')[:16]} refs={d.get('roadmap_refs')} inbox={d.get('inbox_refs')}")
EOF
